#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("USAGE\n");
        return 0;
    }
    char *pattern = argv[1];
    char *string = argv[2];
    int pattern_len = strlen(pattern);
    int string_len = strlen(string);
    int match = 0;
    for (int i = 0; i < string_len; i++) {
        if (pattern[0] == '*') {
            match = 1;
            for (int j = 1; j < pattern_len; j++) {
                if (pattern[j] != '?') {
                    if (string[i + j - 1] != pattern[j]) {
                        match = 0;
                        break;
                    }
                }
            }
        } else if (string[i] == pattern[0]) {
            match = 1;
            for (int j = 1; j < pattern_len; j++) {
                if (pattern[j] != '?') {
                    if (i + j >= string_len || string[i + j] != pattern[j]) {
                        match = 0;
                        break;
                    }
                }
            }
        }
        if (match) break;
    }
    if (match) printf("MATCH\n");
    else printf("NO_MATCH\n");
    return 0;
}
